package com.grad.ventora.blog.service.impl;
import com.grad.ventora.blog.service.*; import com.grad.ventora.blog.dto.*; import com.grad.ventora.blog.entity.*; import com.grad.ventora.blog.repository.*; import com.grad.ventora.exception.exceptions.ResourceNotFoundException;
import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.data.domain.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional
public class BlogServiceImpl implements BlogService {
 private final BlogPostRepository posts; private final BlogCategoryRepository categories; private final BlogPageContentRepository pages;
 private BlogCategory category(Long id){return categories.findById(id).orElseThrow(()->new ResourceNotFoundException("Blog category not found"));}
 private BlogPost post(Long id){return posts.findById(id).orElseThrow(()->new ResourceNotFoundException("Blog post not found"));}
 private BlogCategoryResponse cat(BlogCategory c){return new BlogCategoryResponse(c.getId(),c.getName(),c.getSlug(),c.getDescription(),c.getDisplayOrder(),c.getActive(),posts.countByCategory_IdAndStatus(c.getId(),BlogPostStatus.PUBLISHED));}
 private BlogPostSummaryResponse summary(BlogPost p){return new BlogPostSummaryResponse(p.getId(),p.getTitle(),p.getSlug(),p.getExcerpt(),p.getCoverImageUrl(),p.getAuthorName(),p.getAuthorImageUrl(),p.getCategory().getName(),p.getReadingTime(),p.getPublishedAt(),p.getFeatured());}
 private BlogPostResponse response(BlogPost p){return new BlogPostResponse(p.getId(),p.getTitle(),p.getSlug(),p.getExcerpt(),p.getCoverImageUrl(),p.getContent(),p.getAuthorName(),p.getAuthorImageUrl(),cat(p.getCategory()),p.getReadingTime(),p.getStatus().name(),p.getFeatured(),p.getPublishedAt(),p.getCreatedAt(),p.getUpdatedAt());}
 @Transactional(readOnly=true) public Page<BlogPostSummaryResponse> list(String search,String category,String sort,int page,int size){Pageable pg=PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),50),"oldest".equalsIgnoreCase(sort)?Sort.by("publishedAt").ascending():Sort.by("publishedAt").descending()); Page<BlogPost> result; if(category!=null&&!category.isBlank()){ if(search!=null&&!search.isBlank()) result=posts.findByStatusAndCategory_SlugAndTitleContainingIgnoreCase(BlogPostStatus.PUBLISHED,category,search,pg); else result=posts.findByStatusAndCategory_Slug(BlogPostStatus.PUBLISHED,category,pg); }else if(search!=null&&!search.isBlank()) result=posts.findByStatusAndTitleContainingIgnoreCaseOrStatusAndExcerptContainingIgnoreCase(BlogPostStatus.PUBLISHED,search,BlogPostStatus.PUBLISHED,search,pg); else result=posts.findByStatus(BlogPostStatus.PUBLISHED,pg); return result.map(this::summary);}
 @Transactional(readOnly=true) public BlogPostResponse get(String slug){return response(posts.findBySlugAndStatus(slug,BlogPostStatus.PUBLISHED).orElseThrow(()->new ResourceNotFoundException("Published blog post not found")));}
 @Transactional(readOnly=true) public List<BlogPostSummaryResponse> popular(){return posts.findTop5ByStatusAndFeaturedTrueOrderByPublishedAtDesc(BlogPostStatus.PUBLISHED).stream().map(this::summary).toList();}
 @Transactional(readOnly=true) public Page<BlogPostResponse> adminList(int page,int size){return posts.findAll(PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),50),Sort.by("createdAt").descending())).map(this::response);}
 public BlogPostResponse create(BlogPostRequest r){if(posts.existsBySlug(r.slug()))throw new IllegalArgumentException("Blog post slug already exists"); BlogPost p=new BlogPost(); apply(p,r);p.setStatus(BlogPostStatus.DRAFT);return response(posts.save(p));}
 public BlogPostResponse update(Long id,BlogPostRequest r){BlogPost p=post(id); if(posts.existsBySlug(r.slug())&&!p.getSlug().equals(r.slug()))throw new IllegalArgumentException("Blog post slug already exists");apply(p,r);return response(posts.save(p));}
 private void apply(BlogPost p,BlogPostRequest r){p.setTitle(r.title());p.setSlug(r.slug());p.setExcerpt(r.excerpt());p.setCoverImageUrl(r.coverImageUrl());p.setContent(new ArrayList<>(r.content()));p.setAuthorName(r.authorName());p.setAuthorImageUrl(r.authorImageUrl());p.setCategory(category(r.categoryId()));p.setReadingTime(r.readingTime());p.setFeatured(Boolean.TRUE.equals(r.featured()));}
 public BlogPostResponse publish(Long id){BlogPost p=post(id);p.setStatus(BlogPostStatus.PUBLISHED);if(p.getPublishedAt()==null)p.setPublishedAt(java.time.LocalDateTime.now());return response(posts.save(p));}
 public BlogPostResponse unpublish(Long id){BlogPost p=post(id);p.setStatus(BlogPostStatus.DRAFT);return response(posts.save(p));}
 public void delete(Long id){posts.delete(post(id));}
 @Transactional(readOnly=true) public List<BlogCategoryResponse> categories(boolean admin){return (admin?categories.findAllByOrderByDisplayOrderAsc():categories.findAllByActiveTrueOrderByDisplayOrderAsc()).stream().map(this::cat).toList();}
 public BlogCategoryResponse saveCategory(Long id,BlogCategoryRequest r){BlogCategory c=id==null?new BlogCategory():categories.findById(id).orElseThrow(()->new ResourceNotFoundException("Blog category not found"));if(categories.existsBySlug(r.slug())&&(c.getId()==null||!c.getSlug().equals(r.slug())))throw new IllegalArgumentException("Category slug already exists");c.setName(r.name());c.setSlug(r.slug());c.setDescription(r.description());c.setDisplayOrder(r.displayOrder());c.setActive(r.active()==null||r.active());return cat(categories.save(c));}
 public void deleteCategory(Long id){BlogCategory c=category(id);if(posts.countByCategory_IdAndStatus(id,BlogPostStatus.DRAFT)>0||posts.countByCategory_IdAndStatus(id,BlogPostStatus.PUBLISHED)>0)throw new IllegalStateException("Cannot delete a category that has blog posts");categories.delete(c);}
 private BlogPageContentResponse page(BlogPageContent x){return new BlogPageContentResponse(x.getId(),x.getHeroTitle(),x.getHeroDescription(),x.getBlogTitle(),x.getBlogDescription(),x.getNewsletterTitle(),x.getNewsletterDescription(),x.getBottomCtaTitle(),x.getBottomCtaDescription(),x.getCreatedAt(),x.getUpdatedAt());}
 @Transactional(readOnly=true) public BlogPageContentResponse pageContent(){return pages.findFirstByOrderByIdAsc().map(this::page).orElse(null);} @Transactional(readOnly=true) public BlogPageContentResponse adminPageContent(){return pageContent();}
 public BlogPageContentResponse savePageContent(BlogPageContentRequest r){BlogPageContent x=pages.findFirstByOrderByIdAsc().orElseGet(BlogPageContent::new);x.setHeroTitle(r.heroTitle());x.setHeroDescription(r.heroDescription());x.setBlogTitle(r.blogTitle());x.setBlogDescription(r.blogDescription());x.setNewsletterTitle(r.newsletterTitle());x.setNewsletterDescription(r.newsletterDescription());x.setBottomCtaTitle(r.bottomCtaTitle());x.setBottomCtaDescription(r.bottomCtaDescription());return page(pages.save(x));}
}
